mapper.select:
SELECT el.id AS el_id, el.file_ids AS el_file_ids, el.property_mgt AS el_property_mgt, el.name AS el_name, el.version AS el_version, el.auth AS el_auth, el.project AS el_project, el.description AS el_description, el.tags AS el_tags, el.code_name_params_map_list AS el_code_name_params_map_list, el.modify_user AS el_modify_user, el.modify_time AS el_modify_time, el.create_time AS el_create_time, el.status AS el_status, el.stream_id AS el_stream_id, el.branch_id AS el_branch_id, el.commit_id AS el_commit_id, el.loi_now AS el_loi_now, el.lod_now AS el_lod_now, el.library AS library, elf.id AS elf_id, elf.pid AS elf_pid, elf.name AS elf_name, elf.system AS elf_system, elf.lod AS elf_lod, elf.file_url AS elf_file_url, elf.file_size AS elf_file_size, elf.modify_user AS elf_modify_user, elf.modify_time AS elf_modify_time, elf.status AS elf_status FROM sp_element_library el LEFT JOIN sp_element_library_file elf ON elf.pid = el.id WHERE 1 = 1
AND el.name LIKE CONCAT('%', #{name}, '%')
AND el.tags = #{tags,typeHandler=org.springblade.modules.sp.utils.VarcharArrayTypeHandler}
AND el.project && ARRAY[
#{item}
]::text[]
AND EXISTS ( SELECT 1 FROM jsonb_array_elements(el.property_mgt::jsonb) AS elem WHERE elem->>'基本信息_属性变体' = #{propertyList} )
AND elf.system = #{system}
AND el.lod_now = #{lodNow}
AND (
el.library = #{item}
)
AND el.status = #{status}
ORDER BY el.create_time DESC;

mapper.update:
UPDATE sp_element_library
file_ids = #{fileIds,typeHandler=org.springblade.modules.sp.utils.VarcharArrayTypeHandler}, name = #{name}, version = #{version}, auth = #{auth}, project = #{project,typeHandler=org.springblade.modules.sp.utils.VarcharArrayTypeHandler}, description = #{description}, tags = #{tags,typeHandler=org.springblade.modules.sp.utils.VarcharArrayTypeHandler}, code_name_params_map_list = #{codeNameParamsMapList,typeHandler=org.springblade.modules.sp.utils.JsonListTypeHandler}::jsonb, property_mgt = #{propertyMgt,typeHandler=org.springblade.modules.sp.utils.JsonListTypeHandler}::jsonb, modify_user = #{modifyUser}, status = #{status}, stream_id = #{streamId}, branch_id = #{branchId}, commit_id = #{commitId}, loi_now = #{loiNow}, lod_now = #{lodNow}, modify_time = #{modifyTime}
WHERE id = #{id};
